export default function lengthOfLongestSubstring(s) {
  if (typeof s !== 'string') throw new TypeError('lengthOfLongestSubstring expects a string');
  const lastSeen = new Map();
  let start = 0;
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const previous = lastSeen.get(s[i]);
    if (previous !== undefined && previous >= start) start = previous + 1;
    lastSeen.set(s[i], i);
    best = Math.max(best, i - start + 1);
  }
  return best;
}

