export default function lengthOfLongestSubstring(s) {
  if (typeof s !== 'string') throw new TypeError('lengthOfLongestSubstring expects a string');
  const inWindow = new Set();
  let start = 0;
  let best = 0;
  for (let end = 0; end < s.length; end++) {
    while (inWindow.has(s[end])) {
      inWindow.delete(s[start]);
      start++;
    }
    inWindow.add(s[end]);
    best = Math.max(best, end - start + 1);
  }
  return best;
}
